const additionalDemoDistricts: Record<string, string> = {
  vigo: "Coia, Vigo",
  "a-coruna": "Riazor, A Coruña",
  "santiago-de-compostela": "Fontiñas, Santiago de Compostela",
}

const additionalDemoProfessionals: Professional[] = categories.flatMap((category, categoryIndex) =>
  provinces.map((province) => {
    const existing = originalDemoProfessionals.find(person => person.categoryId === category.id && person.province === province.id)!
    return {
      ...existing,
      id: `demo-${category.id}-${province.id}-additional`,
      name: additionalDemoNames[province.id][categoryIndex],
      location: additionalDemoDistricts[province.id],
      description: `Perfil de demostración de ${existing.category.toLowerCase()} en ${province.name}. No corresponde a un profesional disponible.`,
      verified: false,
    }
  }),
)

export const professionals: Professional[] = [...originalDemoProfessionals, ...additionalDemoProfessionals]

export const footerCategories = categories.slice(0, 6)
export const cities = provinces
export const categoryLinks = footerCategories
export const cityNames = provinces.map((province) => province.name)
export const categoryNames = categories.map((category) => category.name)
export const categorySlugs = categories.map((category) => category.id)
export const getCategory = (id: string) => categories.find((category) => category.id === id)
export const getProvince = (id: string) => provinces.find((province) => province.id === id)
export const getProfessionalsByProvince = (id: string) => professionals.filter((professional) => professional.province === id)
export const getProfessionalsByCategory = (id: string) => professionals.filter((professional) => professional.categoryId === id)
export const slugifyProfessionalName = (name: string) => name
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/^-|-$/g, "")
export const getProfessionalPath = (professional: Professional) => `/${professional.province}/${professional.categoryId}/${slugifyProfessionalName(professional.name)}/`
export const getProfessionalByRoute = (province: string, category: string, slug: string) => professionals.find((professional) => (
  professional.province === province
  && professional.categoryId === category
  && slugifyProfessionalName(professional.name) === slug
))

export default { categories, provinces, professionals }
